Lemma qcw_lit1 : forall len, 1 <= len <= 64 ->
  Z.land (bv_unsigned (Z_to_bv 64 (2147450880 + bv_unsigned (Z_to_bv 64 (188196 + len + -1)) ≫ 3))) 18446744073709551608
  = if len <=? 28 then 2147474400 else 2147474408.
Proof.
  intros len Hl.
  assert (Hc : forall n : nat, (n < 64)%nat ->
    Z.land (bv_unsigned (Z_to_bv 64 (2147450880 + bv_unsigned (Z_to_bv 64 (188196 + (Z.of_nat n + 1) + -1)) ≫ 3))) 18446744073709551608
    = if Z.of_nat n + 1 <=? 28 then 2147474400 else 2147474408).
  { intros n Hn. do 64 (destruct n as [|n]; [vm_compute; reflexivity|]). lia. }
  specialize (Hc (Z.to_nat (len - 1)) ltac:(lia)).
  rewrite Z2Nat.id in Hc by lia.
  replace (len - 1 + 1) with len in Hc by lia.
  exact Hc.
Qed.

